const rows=[
// Everyday Objects
['Toothbrush','oral-care tool','Objects','easy',['My ancestors used twigs.','I usually live near running water.','I work best in small circles.','I visit teeth twice a day.','Bristles and toothpaste are my usual partners.']],
['Umbrella','rain cover','Objects','easy',['I become less useful when the wind wins.','I spend much of my life folded.','I make one person briefly wider.','I open above your head.','I keep rain off you.']],
['Key','lock opener','Objects','easy',['I am copied more often than I am invented.','Losing me can stop a journey.','I often travel on a ring.','My teeth fit something precisely.','I open a lock.']],
['Mirror','reflective surface','Objects','easy',['I reverse without turning anything around.','I am honest about what is in front of me.','Breaking me is linked to an old superstition.','You look into me to see yourself.','I show your reflection.']],
['Pencil','writing tool','Objects','easy',['I grow shorter while doing my job.','My core contains no lead.','One end may undo the other.','I leave gray marks on paper.','You sharpen me to write or draw.']],
['Alarm clock','wake-up device','Objects','easy',['Success often makes me unpopular.','I am set before I am needed.','People bargain with me in nine-minute intervals.','I make noise beside a bed.','I wake you at a chosen time.']],
['Backpack','carried bag','Objects','easy',['I make possessions follow their owner.','My load is shared by two straps.','Students and hikers both rely on me.','I am worn over the shoulders.','I carry things on your back.']],
['Candle','wax light','Objects','easy',['I disappear while working.','A draft can defeat me.','I measure some celebrations in numbers.','A wick runs through my wax.','My flame gives light.']],
['Scissors','cutting tool','Objects','easy',['Two halves achieve what neither can alone.','I pivot around a central point.','Rock defeats me in a hand game.','My paired blades open and close.','I cut paper and fabric.']],
['Zipper','fastener','Objects','medium',['I join two rows one small step at a time.','A tiny slider controls my work.','I can get stuck on fabric.','I commonly close jackets and bags.','My interlocking teeth fasten things.']],
['Thermos','insulated flask','Objects','medium',['I slow change rather than create a temperature.','A vacuum helps me do my job.','I am useful on long journeys.','I keep drinks hot or cold.','I am an insulated bottle.']],
['Compass','direction finder','Objects','medium',['I can point without knowing where I am.','A hidden force moves my most important part.','Explorers used me long before satellites.','My needle aligns north and south.','I help you find direction.']],
['Stapler','paper fastener','Objects','easy',['I bend a small piece of metal out of sight.','My work is often undone by a claw-shaped tool.','I sit on many office desks.','Pressing me joins sheets together.','I fasten paper with staples.']],
['Flashlight','portable light','Objects','easy',['My beam goes where I am pointed.','I am most valuable when normal lighting fails.','Batteries often power me.','I fit a light in your hand.','I illuminate dark places.']],
['Suitcase','travel case','Objects','easy',['I leave home more often than most furniture.','My weight matters at airports.','Wheels made me easier to travel with.','Clothes are packed inside me.','I carry luggage on trips.']],
['Paperclip','wire fastener','Objects','medium',['I became a symbol for attaching digital files.','I do my job without puncturing anything.','I am usually one bent piece of wire.','I temporarily hold sheets together.','I am a small office fastener.']],
['Hourglass','sand timer','Objects','medium',['Turning me over gives me another beginning.','Gravity is my mechanism.','My middle is much narrower than my ends.','Sand falls through me to measure time.','I am a glass timer with two bulbs.']],
['Magnifying glass','hand lens','Objects','easy',['Detectives carry me more often in drawings than in life.','I change appearance, not actual size.','I use a convex lens.','I make small details look larger.','I am a lens held by a handle.']],
['Doorbell','entrance signal','Objects','easy',['Strangers announce themselves through me.','I am pressed but rarely held.','My sound travels farther than the visitor.','I ring inside when someone is at the door.','Press me to announce a caller.']],
['Bubble wrap','protective packaging','Objects','easy',['My destruction is oddly relaxing.','I trap many tiny pockets of air.','I surround fragile deliveries.','People enjoy popping me.','I am plastic packing covered in bubbles.']],

// Food & Drink
['Popcorn','popped corn','Food & Drink','easy',['I am turned inside out by heat.','Most of my siblings never become as large as I do.','I am strongly associated with cinemas.','I begin as a hard kernel.','I pop into a white snack.']],
['Chocolate','cocoa confection','Food & Drink','easy',['My raw origin is bitter, not sweet.','I can bloom without being a flower.','Cacao seeds begin my story.','I melt near body temperature.','I am a sweet often sold in bars.']],
['Sushi','Japanese dish','Food & Drink','easy',['My name points to seasoned grain, not raw fish.','I am often made in small hand-sized pieces.','Seaweed may wrap me.','I usually contain vinegared rice.','I am a Japanese food served with soy sauce.']],
['Croissant','layered pastry','Food & Drink','easy',['My many layers come from repeated folding.','My shape is named for a phase of the Moon.','Butter creates my flaky structure.','I am a crescent-shaped pastry.','I am commonly eaten at breakfast.']],
['Honey','bee-made food','Food & Drink','easy',['I can remain edible for an exceptionally long time when sealed.','My makers collect nectar.','I am stored in wax cells.','Bees produce me.','I am a thick golden sweetener.']],
['Pasta','wheat food','Food & Drink','easy',['My shapes have hundreds of names.','I often begin as flour and water.','I soften in boiling water.','Sauce is commonly served on me.','Spaghetti is one form of me.']],
['Avocado','creamy fruit','Food & Drink','easy',['My seed is far too large to overlook.','I soften after being picked.','My flesh can turn brown in air.','I am the main ingredient in guacamole.','I am a green, creamy fruit.']],
['Coffee','brewed drink','Food & Drink','easy',['I am called a bean but begin as a seed inside a fruit.','Roasting transforms my aroma.','Caffeine is part of my reputation.','I am brewed with hot water.','Many people drink me in the morning.']],
['Pretzel','twisted bread','Food & Drink','medium',['My silhouette resembles folded arms.','A special alkaline bath helps create my crust.','I am often sprinkled with coarse salt.','I am bread shaped into a knot.','I am a twisted baked snack.']],
['Pineapple','tropical fruit','Food & Drink','easy',['I am many fruits fused into one.','A crown grows on my top.','My rough skin forms a diamond pattern.','I am yellow and sweet inside.','I am a spiky tropical fruit.']],
['Yogurt','cultured dairy food','Food & Drink','easy',['Living cultures help make me.','I become tangy through fermentation.','I am kept chilled and eaten with a spoon.','I am made by fermenting milk.','I am a creamy dairy food.']],
['Cinnamon','aromatic spice','Food & Drink','medium',['I am bark pretending to be a stick.','I curl as I dry.','I am both woody and sweet-smelling.','I am ground onto pastries and drinks.','I am a brown spice from tree bark.']],
['Watermelon','large melon','Food & Drink','easy',['My name promises exactly what fills most of me.','My seeds inspired a familiar color contrast.','I have a hard green rind.','I am red or pink and juicy inside.','I am a very large summer melon.']],
['Cheese','cultured milk food','Food & Drink','easy',['Time can increase my value.','Tiny organisms help create my variety.','I may be soft, hard, blue, or full of holes.','I am made from milk curds.','I am sliced onto sandwiches and pizza.']],
['Tea','infused drink','Food & Drink','easy',['Green and black versions can come from the same plant.','Water temperature changes my result.','My leaves are steeped, not eaten.','I am often served from a pot.','I am a hot drink made by infusing leaves.']],
['Taco','folded food','Food & Drink','easy',['My container is part of the meal.','I may be crisp or soft.','Fillings sit inside a folded tortilla.','I am strongly associated with Mexican cuisine.','I am a filled tortilla eaten by hand.']],
['Ice cream','frozen dessert','Food & Drink','easy',['Air is one of my important ingredients.','I must be churned to stay smooth.','I melt faster on hot days.','I am served in scoops, cones, or bowls.','I am a sweet frozen dairy dessert.']],
['Banana','curved fruit','Food & Drink','easy',['I travel better before I turn yellow.','My skin opens without a knife.','I often grow in a cluster called a hand.','I am a curved fruit with a peel.','I turn from green to yellow as I ripen.']],
['Salt','mineral seasoning','Food & Drink','easy',['I once served as valuable payment.','I can preserve food by drawing out water.','The sea contains a great deal of me.','I come in crystals and make food taste saltier.','My chemical name is sodium chloride.']],
['Doughnut','ring-shaped pastry','Food & Drink','easy',['My absence may be as recognizable as my substance.','I often take a bath in hot oil.','Glaze and sprinkles may cover me.','I am commonly shaped like a ring.','I am a sweet fried pastry.']],

// Animals
['Octopus','eight-armed mollusc','Animals','easy',['I taste with parts that also help me walk.','Three hearts keep me going.','I can change both color and texture.','I have eight arms with suckers.','I am a highly intelligent sea animal.']],
['Giraffe','tall African mammal','Animals','easy',['I have the same number of neck bones as a human.','My heart must pump blood a long way upward.','My patterned coat is unique to me.','I have an exceptionally long neck.','I am the tallest living land animal.']],
['Penguin','flightless seabird','Animals','easy',['My knees are hidden inside my body.','I fly through water instead of air.','Many of my kind live far from the North Pole.','I am a black-and-white flightless bird.','I waddle and swim in cold oceans.']],
['Chameleon','color-changing lizard','Animals','easy',['My eyes can aim in different directions.','My tongue can travel farther than my body length.','My feet grip branches like tongs.','I can change skin color.','I am a tree-dwelling lizard.']],
['Dolphin','marine mammal','Animals','easy',['I sleep with only part of my brain at a time.','Sound helps me build a picture of my surroundings.','I breathe air through a blowhole.','I am an intelligent marine mammal.','I am known for leaping beside boats.']],
['Sloth','slow tree mammal','Animals','easy',['A tiny ecosystem may grow in my fur.','I conserve energy with an unusually slow metabolism.','I spend much of my life hanging upside down.','I move very slowly through trees.','I am a shaggy Central and South American mammal.']],
['Peacock','ornamental bird','Animals','easy',['The famous display belongs to the male.','My eyespots are not eyes.','I shake a huge fan during courtship.','I have brilliant blue and green feathers.','I am a bird known for a spectacular tail.']],
['Kangaroo','hopping marsupial','Animals','easy',['Moving backward is difficult for me.','My tail can act like an extra limb.','My young continues growing in a pouch.','I travel with powerful hops.','I am an Australian marsupial.']],
['Owl','nocturnal bird of prey','Animals','easy',['My eyes are tubes rather than round balls.','Silent edges on my feathers soften flight noise.','I turn my head because my eyes barely move.','I hunt mostly at night.','I am a bird famous for hooting.']],
['Seahorse','upright fish','Animals','medium',['The father carries the developing young.','I swim upright, which is unusual for fish.','My tail can grip plants.','My head resembles that of a horse.','I am a tiny armored sea fish.']],
['Axolotl','aquatic salamander','Animals','hard',['I keep youthful features throughout adulthood.','I can regrow complex body parts.','Feathery gills frame my head.','I am an aquatic salamander from Mexico.','I often look as though I am smiling.']],
['Platypus','egg-laying mammal','Animals','medium',['My discovery looked like a stitched-together hoax.','The male carries venomous spurs.','I detect prey using electrical signals.','I am a duck-billed mammal that lays eggs.','I live in rivers of eastern Australia.']],
['Flamingo','pink wading bird','Animals','easy',['I eat with my head upside down.','My food helps color my feathers.','I often balance on one leg.','I am a tall pink wading bird.','Large groups of me are called flamboyances.']],
['Bat','flying mammal','Animals','easy',['My fingers support my wings.','Some of my kind pollinate important plants.','Many of us navigate using echoes.','I am active mainly at night.','I am the only mammal capable of sustained flight.']],
['Elephant','largest land mammal','Animals','easy',['I can communicate with sounds too low for people to hear.','My family groups are led by experienced females.','My nose also works as a hand.','I have tusks and enormous ears.','I am the largest living land animal.']],
['Honeybee','social pollinating insect','Animals','easy',['I give directions by dancing.','My society has workers, drones, and a queen.','Flowers trade nectar for my transport service.','I live in a hive and make honey.','I am a striped pollinating insect.']],
['Cheetah','fast spotted cat','Animals','easy',['My claws do not retract completely.','Dark lines run from my eyes toward my mouth.','I rely on acceleration more than endurance.','I am a slender spotted African cat.','I am the fastest land animal.']],
['Turtle','shelled reptile','Animals','easy',['My skeleton includes my portable shelter.','I cannot crawl out of my shell.','Some of my kind cross oceans to nest.','I am a slow-moving reptile with a shell.','I may live on land or in water.']],
['Hummingbird','tiny hovering bird','Animals','easy',['I can travel backward under my own power.','My wings make the sound in my name.','Hovering lets me drink while airborne.','I sip nectar with a long bill.','I am a tiny, fast-winged bird.']],
['Polar bear','Arctic bear','Animals','easy',['My skin is dark beneath a pale-looking coat.','My hairs are transparent rather than truly white.','I am an excellent long-distance swimmer.','I hunt seals on Arctic sea ice.','I am the largest bear species.']],

// Places
['Eiffel Tower','Paris landmark','Places','easy',['I was intended to stand for only about twenty years.','Radio experiments helped preserve me.','My height changes slightly with temperature.','I am an iron landmark beside the Seine.','I tower over Paris.']],
['Sahara Desert','North African desert','Places','easy',['I was greener during parts of the distant past.','I stretch across many national borders.','Sand covers less of me than many imagine.','I occupy much of North Africa.','I am the world’s largest hot desert.']],
['Mount Everest','highest mountain above sea level','Places','easy',['My rock began beneath an ancient ocean.','I am still changing as tectonic plates move.','Two countries meet at my summit.','Climbers call my highest point the top of the world.','I am Earth’s highest mountain above sea level.']],
['Great Barrier Reef','coral reef system','Places','easy',['Tiny animals built much of my enormous structure.','I am not one continuous object.','I run along the coast of Queensland.','I am a vast Australian coral ecosystem.','I am the world’s largest coral reef system.']],
['Venice','Italian canal city','Places','easy',['My foundations rest on countless wooden piles.','High water periodically enters my streets.','Boats replace cars in my historic center.','Gondolas travel through my canals.','I am an Italian city built across islands.']],
['Grand Canyon','Arizona canyon','Places','easy',['My exposed layers read like pages of deep time.','A river continues to shape me.','My width makes the opposite rim look deceptively close.','I cut across northern Arizona.','I am a vast canyon carved by the Colorado River.']],
['Machu Picchu','Inca mountain site','Places','easy',['The outside world overlooked me for centuries, though locals did not.','My stones fit together with remarkable precision.','I sit high in the Andes.','I was built by the Inca.','I am a famous ruined city in Peru.']],
['Antarctica','southern polar continent','Places','easy',['I am technically the largest desert on Earth.','No country owns all of me.','Most of the planet’s fresh ice rests here.','I surround the South Pole.','I am Earth’s coldest continent.']],
['Amazon rainforest','South American rainforest','Places','easy',['I make much of my own rain.','My rivers move an immense amount of fresh water.','I span several countries.','Extraordinary biodiversity fills my canopy.','I am the vast tropical forest of South America.']],
['Dead Sea','hypersaline lake','Places','medium',['My name exaggerates, but not by much.','People float unusually high in my water.','My shores sit below sea level.','Salt makes me hostile to most aquatic life.','I am a hypersaline lake between Jordan and Israel and the West Bank.']],
['Stonehenge','prehistoric stone monument','Places','easy',['Some of my stones traveled surprisingly far.','My builders left no written explanation.','Solstice sunlight aligns with part of me.','I am a prehistoric ring of standing stones.','I stand on Salisbury Plain in England.']],
['Niagara Falls','waterfall group','Places','easy',['I have moved backward as water eroded my edge.','I am three waterfalls, not one.','Two countries share me.','Huge volumes of water plunge over my cliffs.','I lie between Canada and the United States.']],
['Petra','rock-cut ancient city','Places','medium',['Visitors approach me through a narrow gorge.','My builders mastered desert water management.','Many of my facades are carved directly into rock.','My rose-colored Treasury is famous.','I am an ancient city in Jordan.']],
['Serengeti','East African ecosystem','Places','medium',['My name is linked to an idea of endless plains.','Seasonal rain drives an enormous migration here.','Tanzania contains most of me.','Wildebeest and zebras cross my grasslands.','I am a celebrated East African safari ecosystem.']],
['Galápagos Islands','Pacific volcanic archipelago','Places','medium',['Isolation made me a natural laboratory.','My wildlife helped reshape ideas about evolution.','I sit on both sides of the Equator.','Giant tortoises live on my volcanic islands.','I am an Ecuadorian archipelago in the Pacific.']],
['Pyramids of Giza','ancient Egyptian monuments','Places','easy',['I was already ancient when Rome was young.','My original outer surfaces were smoother and brighter.','One of me is the only surviving ancient world wonder.','I stand beside Cairo.','I am a group of monumental Egyptian tombs.']],
['Sydney Opera House','Australian performing-arts landmark','Places','easy',['My roof pieces are sections of the same imagined sphere.','My construction took far longer than first planned.','My silhouette suggests sails or shells.','I stand beside Sydney Harbour.','I am Australia’s famous performing-arts building.']],
['Mount Fuji','Japanese volcano','Places','easy',['My near symmetry has inspired artists for centuries.','Pilgrims have long climbed me.','Snow often caps my cone.','I am a volcano visible from Tokyo on clear days.','I am Japan’s highest mountain.']],
['Times Square','New York public square','Places','easy',['My modern name came from a newspaper.','A ball descends here once each year.','Electronic signs dominate the view.','Broadway crosses this busy Manhattan area.','I am New York’s brightly lit gathering place.']],
['Santorini','Greek volcanic island','Places','medium',['A massive ancient eruption shaped my center.','White buildings cling to cliffs above a flooded caldera.','Blue domes appear in countless photographs.','I am an island in the Aegean Sea.','I am a famous Greek destination formed by a volcano.']],

// Science & Nature
['Moon','Earth’s natural satellite','Science & Nature','easy',['I am moving away from you by a few centimeters each year.','The same side usually faces Earth.','My pull helps drive ocean tides.','I change apparent shape through a monthly cycle.','I am Earth’s natural satellite.']],
['Rainbow','optical arc','Science & Nature','easy',['I am a circle you usually see only part of.','Every observer has a slightly different version of me.','Water droplets split and reflect light to make me.','I appear opposite the Sun.','I am a multicolored arc after rain.']],
['Lightning','electrical discharge','Science & Nature','easy',['I make nearby air hotter than the surface of the Sun.','You see me before you hear my consequence.','Charge builds before I bridge a gap.','Thunder follows me.','I am a giant electrical spark in the atmosphere.']],
['Volcano','erupting landform','Science & Nature','easy',['I can create land while destroying what stands on it.','Pressure builds beneath my surface.','Some of my relatives sleep for centuries.','Lava may flow from my opening.','I am a mountain or vent that erupts magma.']],
['Aurora','polar light display','Science & Nature','medium',['I begin with particles from a star.','A magnetic field guides my makers poleward.','Different gases help create my colors.','I ripple across high-latitude night skies.','I am the northern or southern lights.']],
['Black hole','collapsed cosmic object','Science & Nature','medium',['I am recognized through effects on things around me.','Crossing my boundary makes return impossible.','My gravity bends light dramatically.','Some massive stars can collapse into me.','I am a region from which not even light escapes.']],
['DNA','genetic molecule','Science & Nature','easy',['Four chemical letters encode my messages.','Nearly every cell carries a long copy of me.','My shape resembles a twisted ladder.','Genes are sections of me.','I store hereditary information.']],
['Earthquake','ground-shaking event','Science & Nature','easy',['My starting point underground is not my epicenter.','I can make distant water slosh.','Faults release stored energy to create me.','Seismographs record my waves.','I make the ground shake.']],
['Solar eclipse','Sun-blocking alignment','Science & Nature','easy',['My shadow travels faster than anyone can run.','I can turn daytime briefly dark.','Three worlds must line up precisely.','The Moon passes between Earth and the Sun.','I hide the Sun for observers in my path.']],
['Coral','reef-building animal','Science & Nature','medium',['I look like a plant or rock but belong to the animal kingdom.','Tiny partners living in my tissues provide much of my energy.','Warm-water stress can drain my color.','Colonies of me build reefs.','I am a small marine animal with a hard skeleton.']],
['Tornado','rotating wind column','Science & Nature','easy',['I can be invisible until debris or condensation outlines me.','A rotating storm may lower me toward the ground.','My path can be narrow but devastating.','I often look like a funnel.','I am a violently rotating column of air touching the ground.']],
['Glacier','moving mass of ice','Science & Nature','easy',['I flow even though I look still.','I carve valleys and transport boulders.','Snow compressed over years creates me.','Large cracks called crevasses open on me.','I am a slow-moving river of ice.']],
['Photosynthesis','light-powered biological process','Science & Nature','medium',['I turn an invisible gas into living material.','A green pigment captures my energy source.','I release oxygen as part of my work.','Plants use sunlight during me.','I convert light, water, and carbon dioxide into sugars.']],
['Saturn','ringed planet','Science & Nature','easy',['I would float if a bathtub could hold me.','My day is much shorter than Earth’s.','Ice and rock form my most famous feature.','I am the sixth planet from the Sun.','I am the gas giant with spectacular rings.']],
['Comet','icy solar-system body','Science & Nature','easy',['My most visible feature points away from the Sun.','Heat makes me shed material as I approach our star.','I spend much of my time in deep cold.','I may grow a glowing tail.','I am an icy body orbiting the Sun.']],
['Atom','basic unit of matter','Science & Nature','easy',['I am mostly empty space.','Changing my proton count changes my identity.','Electrons occupy regions around my center.','Molecules are built from me.','I am a basic unit of a chemical element.']],
['Tide','regular sea-level change','Science & Nature','easy',['I turn shorelines into temporary places.','The Sun assists, but a nearer neighbor has more influence.','I usually rise and fall on a predictable cycle.','The Moon’s gravity helps cause me.','I am the periodic movement of sea level.']],
['Snowflake','ice crystal','Science & Nature','easy',['Six is the organizing number in my design.','My journey through changing air shapes me.','I begin around a tiny particle in a cloud.','I melt when held in a warm hand.','I am a delicate ice crystal that falls as snow.']],
['Magnet','magnetic object','Science & Nature','easy',['Breaking me creates smaller pairs, not a single end.','I can act without touching.','Like poles repel and unlike poles attract.','Iron is strongly drawn to me.','I have north and south poles.']],
['Fossil','preserved ancient trace','Science & Nature','easy',['I am evidence rather than the original living thing.','Mud can protect my story for millions of years.','Footprints can become me too.','Paleontologists search rocks for me.','I preserve remains or traces of ancient life.']],

// Technology
['Wi-Fi','wireless networking','Technology','easy',['My familiar name was designed to be memorable, not technical.','Walls and distance can weaken me.','A router commonly provides me.','I connect devices without cables.','I provide wireless access to a computer network.']],
['QR code','square machine-readable code','Technology','easy',['I can still work when part of me is damaged.','Three large squares help a camera orient me.','Restaurants often use me instead of printed menus.','A phone camera can read me.','I am a square black-and-white code.']],
['Bluetooth','short-range wireless standard','Technology','easy',['I was named for a medieval Scandinavian king.','My symbol combines two old runic letters.','I work best over short distances.','I connect headphones and devices wirelessly.','I am a wireless technology named Bluetooth.']],
['Computer mouse','pointing device','Technology','easy',['My name came from my shape and trailing cord.','A small arrow follows my movement.','I have buttons but type no letters.','I point, click, and drag on a computer.','I am the hand-held device beside a keyboard.']],
['USB','device connection standard','Technology','easy',['My orientation once seemed wrong on the first try surprisingly often.','One connector can carry both power and data.','Many shapes and generations share my name.','I connect and charge electronic devices.','Flash drives commonly plug into my port.']],
['GPS','satellite navigation system','Technology','easy',['Time errors of tiny fractions would send me far off course.','I need signals from multiple clocks in orbit.','Your receiver usually listens rather than transmits.','Maps use me to show your position.','I am a satellite-based navigation system.']],
['Emoji','digital pictograph','Technology','easy',['My name is Japanese and is unrelated to the English word emotion.','My appearance changes across platforms.','I can replace tone that plain text lacks.','I am inserted into messages from a tiny picture keyboard.','I am a colorful symbol such as a face or heart.']],
['Password','secret access string','Technology','easy',['Sharing me makes me less useful.','Long and unique usually beats clever and short.','A manager can remember many of me for you.','I am entered to prove access.','I am a secret string protecting an account.']],
['Drone','uncrewed aircraft','Technology','easy',['My pilot may remain on the ground.','Several spinning rotors often hold me aloft.','Cameras are a common payload.','I can hover and fly by remote control.','I am an uncrewed aircraft.']],
['3D printer','additive manufacturing machine','Technology','easy',['I make objects by adding rather than cutting away.','My creations often begin as stacked layers.','A digital model guides me.','I can build plastic parts on a desktop.','I am a printer that creates solid objects.']],
['Cloud computing','remote internet computing','Technology','medium',['My weather-like name hides very physical buildings.','Distance makes someone else’s machine feel local.','Storage and processing can both move into me.','Internet services run on remote servers through me.','I am computing delivered from the cloud.']],
['Touchscreen','touch-sensitive display','Technology','easy',['I removed many buttons by pretending to be all of them.','My picture and control surface are the same place.','Pinching me can make content grow smaller.','Phones respond when fingers tap me.','I am a display controlled by touch.']],
['Robot','programmable machine','Technology','easy',['My name came from a word associated with forced labor.','I need not look human.','Sensors help me respond to surroundings.','Factories use me for repetitive tasks.','I am a programmable machine that acts in the physical world.']],
['Camera','image-making device','Technology','easy',['I borrow the word for a room.','A brief opening controls how much light enters.','Focus decides what looks sharp.','I capture photographs through a lens.','I am a device for making images.']],
['Microphone','sound input device','Technology','easy',['I turn moving air into an electrical signal.','Getting too close can exaggerate low sounds.','Performers speak or sing into me.','I record and amplify voices.','I am a device that captures sound.']],
['Solar panel','sunlight electricity panel','Technology','easy',['I work without any moving parts.','Shadows across a small section can reduce my output.','My cells convert incoming light directly.','I am often mounted on roofs.','I generate electricity from sunlight.']],
['Barcode','machine-readable stripe code','Technology','easy',['The quiet blank space around me is part of my design.','My widths matter more than my printed height.','A beam reads my pattern at checkout.','I appear as parallel black lines on products.','I encode an item number for a scanner.']],
['Email','electronic mail','Technology','easy',['My addressing symbol was once relatively obscure.','I existed before the public web.','Spam fills an unwanted portion of me.','I arrive in an inbox over the internet.','I am electronic mail.']],
['Search engine','web-finding service','Technology','easy',['Crawlers gather what I later retrieve.','Ranking matters as much as matching.','A few words send me through a huge index.','I return links for an internet query.','I help you find pages on the web.']],
['Satellite','orbiting artificial object','Technology','easy',['Falling continuously can keep me from hitting the ground.','Some of my kind watch weather; others relay signals.','Rockets place me where I work.','I circle Earth in space.','I am an artificial object in orbit.']],

// History & Inventions
['Printing press','mass-printing machine','History','easy',['I made copying less dependent on a steady hand.','Movable pieces let pages be rearranged.','My spread transformed who could encounter books.','Gutenberg is closely associated with me in Europe.','I am a machine for mass-producing printed pages.']],
['Wheel','rotating invention','History','easy',['My earliest known uses may have shaped clay before transport.','An axle makes me far more useful.','I turn sliding friction into rolling motion.','Carts and bicycles depend on me.','I am a circular invention that rolls.']],
['Compass rose','map direction symbol','History','medium',['I flower on paper but never grow.','My points can number four, eight, sixteen, or more.','Cartographers place me on maps.','I mark north, south, east, and west.','I am the star-like direction symbol on a map.']],
['Rosetta Stone','multilingual ancient artifact','History','medium',['The message mattered less than its repetition.','Three scripts share my surface.','I unlocked reading that had been lost.','I helped scholars decipher Egyptian hieroglyphs.','I am a carved stone found near Rosetta.']],
['Titanic','ocean liner','History','easy',['My fame rests on a journey I never completed.','Too few lifeboat places became part of my tragedy.','An iceberg damaged me in the North Atlantic.','I sank on my maiden voyage in 1912.','I was a supposedly unsinkable ocean liner.']],
['Magna Carta','medieval English charter','History','medium',['Most of my original promises addressed a narrow elite.','A king accepted me under political pressure.','Later generations made me a symbol of legal limits.','I was sealed at Runnymede in 1215.','I am the English charter called the Great Charter.']],
['Silk Road','historic trade network','History','easy',['I was many routes, despite my singular name.','Ideas and diseases traveled with merchandise along me.','Caravans connected distant markets.','I linked East Asia with lands to the west.','I am the ancient trade network named for a luxury fabric.']],
['Steam engine','heat-powered engine','History','easy',['I turn expanding vapor into motion.','Pumping water was one of my early major jobs.','I helped factories separate from river power.','Coal commonly heated the water I used.','I powered locomotives during industrialization.']],
['Lighthouse','coastal warning tower','History','easy',['My message is understood by timing, not words.','Different flash patterns identify different locations.','I stand where land can threaten ships.','A strong light shines from my tower.','I guide mariners away from danger.']],
['Sundial','shadow timekeeper','History','easy',['Clouds can make me forget the time.','I have no gears or batteries.','A raised pointer casts my moving indicator.','The Sun makes my shadow tell time.','I am an ancient outdoor clock.']],
['Typewriter','mechanical writing machine','History','easy',['My limitations helped shape a keyboard still used today.','A bell warns that my line is nearly full.','Metal arms strike an inked ribbon.','I put letters on paper one key at a time.','I am the mechanical ancestor of word processing.']],
['Telegraph','long-distance signaling system','History','medium',['My messages became shorter because every word cost money.','Dots and dashes were one way to speak through me.','Wires let news outrun trains and ships.','Operators sent coded electrical pulses.','I was a major long-distance communication system before telephones.']],
['Hot-air balloon','lighter-than-air aircraft','History','easy',['My passengers travel with the wind rather than against it.','Heating my contents reduces their density.','A basket hangs beneath my envelope.','I rise when a burner warms the air inside.','I am a colorful balloon large enough to carry people.']],
['Pocket watch','portable timepiece','History','easy',['A chain often prevented my freedom.','A protective lid may cover my face.','I made personal time portable before wristwear dominated.','I am carried in a waistcoat or trouser pocket.','I am a small clock on a chain.']],
['Phonograph','early sound player','History','medium',['I made voices outlive the moment of speaking.','A needle follows a physical groove.','Early versions recorded on cylinders.','A horn amplifies my sound.','I am an early machine for recording and playing audio.']],
['Windmill','wind-powered machine','History','easy',['My spinning arms can do work without electricity.','I have ground grain and pumped water.','Wind pushes my sails or blades.','Traditional Dutch landscapes feature me.','I am a tower-mounted machine powered by wind.']],
['Abacus','manual calculating frame','History','easy',['Place value moves beneath your fingers.','I can calculate without writing a numeral.','Beads slide along rods or wires.','Merchants have used me for arithmetic.','I am an ancient counting frame.']],
['Hour hand','clock pointer','History','easy',['I finish one lap while my faster partner finishes twelve.','My small movement still matters.','I point toward numbered positions.','I am usually the shorter pointer on a clock.','I show the hour.']],
['Parachute','descent-slowing canopy','History','easy',['Air resistance is my entire strategy.','I am packed small before becoming very large.','Cords connect my canopy to a person or cargo.','I slow a fall from the sky.','Skydivers open me before landing.']],
['Morse code','dot-and-dash code','History','easy',['My pauses carry information too.','One of my shortest messages represents a very common letter.','Light, sound, or electricity can transmit me.','I encode letters using dots and dashes.','SOS is famously sent with me.']],

// Entertainment & Games
['Chess','strategy board game','Entertainment','easy',['My most important piece is not my most powerful.','Every battle begins with equal armies.','A pawn can return transformed.','I am played on sixty-four squares.','Kings, queens, rooks, bishops, and knights move in me.']],
['Rubik’s Cube','twisting color puzzle','Entertainment','easy',['There are vastly more arrangements of me than seconds in human history.','My centers define the final color of each face.','I twist but do not come apart during proper play.','I have six colored faces.','I am a cube-shaped puzzle solved by matching colors.']],
['Karaoke','sing-along entertainment','Entertainment','easy',['My name combines Japanese words for empty and orchestra.','Missing vocals are my main feature.','Lyrics appear while music plays.','Amateurs sing popular songs into a microphone.','I am public sing-along entertainment.']],
['Jigsaw puzzle','interlocking picture puzzle','Entertainment','easy',['My name remembers a tool once used to make me.','My edge pieces are usually found first.','A complete image is broken into irregular parts.','Tabs and blanks connect my pieces.','I am a picture assembled on a table.']],
['Yo-yo','spinning string toy','Entertainment','easy',['I can sleep without closing eyes.','My simplest journey ends where it began.','A string winds around my axle.','I travel down and back up from a hand.','I am a round toy used for tricks.']],
['Origami','paper-folding art','Entertainment','easy',['Cuts and glue are traditionally absent from my purest form.','A flat square can become an animal.','Precision creases matter to me.','I am strongly associated with Japanese culture.','I am the art of folding paper.']],
['Dominoes','marked tile game','Entertainment','easy',['My name also describes a chain reaction.','Each of my rectangular pieces has two ends.','Dots represent numbers on my face.','Players match my adjacent values.','I am a game played with black-and-white tiles.']],
['Sudoku','number-placement puzzle','Entertainment','easy',['Arithmetic is irrelevant despite my digits.','Repetition is forbidden along three kinds of region.','I usually use a nine-by-nine grid.','Every row and column needs digits one through nine.','I am a logic puzzle from newspapers.']],
['Magic trick','performed illusion','Entertainment','easy',['Knowing me often makes me less entertaining.','Attention is guided away from the method.','Practice hides difficult movements.','A magician performs me.','I create an apparently impossible effect.']],
['Comic book','illustrated sequential story','Entertainment','easy',['My silence is filled with written sounds.','Time moves through the spaces between my panels.','Speech often floats inside balloons.','I tell stories with sequential pictures.','Superheroes commonly appear in me.']],
['Ballet','theatrical dance form','Entertainment','easy',['Effort is concealed beneath apparent weightlessness.','A special shoe can support dancing on toe tips.','My vocabulary uses many French terms.','I combine formal dance and music on a stage.','Tutus are closely associated with me.']],
['Ukulele','small four-string instrument','Entertainment','easy',['My name is often translated with an image of a jumping flea.','I arrived in Hawaii through Portuguese influence.','I usually has four strings.','I resembles a small guitar.','I am a bright-sounding Hawaiian instrument.']],
['Violin','bowed string instrument','Entertainment','easy',['My hollow body amplifies without electricity.','A bow makes my strings speak.','I am held between chin and shoulder.','I have four strings and no frets.','I am the smallest standard orchestral string instrument.']],
['Drum kit','grouped percussion instrument','Entertainment','easy',['One player becomes an entire rhythm section.','Feet and hands work independently to play me.','Cymbals rise above my round components.','I include a snare and bass drum.','I am the percussion setup behind many bands.']],
['Movie trailer','film preview','Entertainment','easy',['My name survives from when I actually followed the feature.','I compress a long story while trying not to spoil it.','Music and quick cuts build anticipation.','I play before films at a cinema.','I am an advertisement previewing a movie.']],
['Shadow puppet','silhouette performance figure','Entertainment','medium',['The audience sees my absence of light.','Distance can change my apparent size.','Hands, sticks, or cutouts create my shape.','A lamp projects me onto a screen.','I am a puppet seen as a shadow.']],
['Crossword','intersecting word puzzle','Entertainment','easy',['Every answer borrows letters from others.','Dark squares divide my small world.','Across and down are my two directions.','Clues fill words into a grid.','I am a newspaper word puzzle.']],
['Playing card','game card','Entertainment','easy',['One side must reveal nothing useful.','Four families share my standard pack.','Courts appear among my ranks.','I may be a heart, diamond, club, or spade.','I am one of fifty-two in a common deck.']],
['Marionette','string-controlled puppet','Entertainment','medium',['My freedom depends on carefully managed restraints.','A controller hovers above me.','Strings move my limbs.','I perform on a miniature stage.','I am a puppet operated from above.']],
['Stop-motion animation','frame-by-frame animation','Entertainment','medium',['My actors remain still almost all the time.','Tiny changes create an illusion when viewed quickly.','One photograph captures each pose.','Clay figures often star in me.','I am animation made by moving objects frame by frame.']],

// Sports
['Football','global team ball sport','Sports','easy',['Most players may not use the body part that gives another sport its name.','A rectangle of netting waits at each end.','Eleven players usually start for each side.','Goals are scored mainly with the feet.','I am the sport also called soccer.']],
['Basketball','hoop sport','Sports','easy',['My original targets were fruit containers.','A shot can be worth one, two, or three.','Players dribble while moving.','Two raised hoops are my goals.','I am played with an orange bouncing ball.']],
['Tennis','racket net sport','Sports','easy',['Love means nothing in my scoring.','My zero-to-first-point jump is unusually large.','Players alternate hitting over a net.','I use rackets and a fuzzy ball.','Wimbledon is a famous tournament in me.']],
['Marathon','long-distance foot race','Sports','easy',['My distance was standardized after an early modern Olympic route.','A wall can appear without bricks late in my course.','I am longer than forty-two kilometres.','Runners cover 26.2 miles.','I am a famous long-distance road race.']],
['Surfing','wave-riding sport','Sports','easy',['My playing surface travels beneath me.','Balance and timing replace an engine.','A leash often connects athlete and equipment.','I am performed on ocean waves.','Riders stand on a board.']],
['Archery','bow-and-arrow sport','Sports','easy',['My perfect result lands in a color associated with wealth.','Stillness matters before sudden motion.','A string launches my projectile.','Competitors aim at concentric circles.','I am the sport of shooting arrows with a bow.']],
['Table tennis','small-table racket sport','Sports','easy',['My ball is extremely light and hollow.','The playing surface divides my name from a larger cousin.','Fast rallies cross a low net.','Small paddles strike my ball.','I am also called ping-pong.']],
['Fencing','sword combat sport','Sports','easy',['My clothing is connected by a wire at high levels.','A light can decide whether contact counted.','Three different weapons define my events.','Masked opponents duel on a narrow strip.','I am the sport of competitive sword fighting.']],
['Golf','club-and-ball sport','Sports','easy',['Less is better on my scoreboard.','My destination is much smaller than my starting area.','Courses commonly have eighteen holes.','Clubs strike a small dimpled ball.','Players try to put the ball into cups.']],
['Cricket','bat-and-ball sport','Sports','easy',['A match can last much longer than most sporting events.','My central strip is called a pitch.','Bowlers attack three wooden stumps.','Batters can score by running between wickets.','I am a bat-and-ball sport popular across many continents.']],
['Volleyball','net team sport','Sports','easy',['Keeping my ball off the floor matters more than possessing it.','A team normally gets three touches before returning me.','Players rotate positions.','Hands send a ball over a high net.','I am played in gyms and on beaches.']],
['Skiing','snow-gliding sport','Sports','easy',['Two narrow surfaces make one person faster downhill.','Gravity provides much of my power.','Poles may help with balance and propulsion.','Boots attach to long runners.','I am the sport of gliding over snow.']],
['Boxing','gloved combat sport','Sports','easy',['My square has a circular name.','A count can end a contest without a final bell.','Padded gloves protect and deliver punches.','Two fighters compete in rounds.','I am a combat sport using fists.']],
['Baseball','bat-and-ball diamond sport','Sports','easy',['Failing three times can end one small opportunity.','My field has a diamond but no jewelry.','Runners travel through four bases.','A pitcher throws toward a batter.','I am played in nine innings.']],
['High jump','athletics jumping event','Sports','easy',['Success makes the next task literally higher.','Landing safely requires falling backward onto a mat.','A flexible bar rests on two supports.','Athletes leap over the bar without a pole.','I am a track-and-field jumping event.']],
['Curling','ice stone sport','Sports','medium',['Sweeping changes my path without touching my moving object.','My target is called the house.','Heavy stones slide over pebbled ice.','Teams use brooms and careful strategy.','I am a winter sport sometimes called chess on ice.']],
['Rowing','oar-powered boat sport','Sports','easy',['Competitors face away from their destination.','Several people can move as one machine.','Long blades push against water.','Races take place in narrow boats.','I am the sport of propelling a boat with oars.']],
['Badminton','shuttlecock racket sport','Sports','easy',['My projectile is designed to slow dramatically.','Feathers can make up its skirt.','Rackets send it across a net.','Players hit a shuttlecock.','I am an indoor sport with singles and doubles.']],
['Cycling','bicycle sport','Sports','easy',['Drafting lets one competitor borrow another’s effort.','Two thin contact patches connect athlete to road.','Gears trade speed for force.','Riders pedal two-wheeled machines.','I am the sport of racing bicycles.']],
['Gymnastics','acrobatic sport','Sports','easy',['A tenth of a point can separate elegance from a medal.','Strength is often disguised as grace.','Beams, bars, rings, and mats host my events.','Athletes flip, twist, and balance.','I am an Olympic acrobatic sport.']],

// Human Body, Language & Culture
['Fingerprint','unique skin-ridge pattern','Body & Culture','easy',['I form before birth and grow without changing my basic layout.','Sweat helps me leave a trace.','Loops, whorls, and arches describe my patterns.','I am used to identify people.','I am the ridge pattern on a fingertip.']],
['Hiccup','involuntary spasm','Body & Culture','easy',['My sound arrives after a muscle moves unexpectedly.','I can repeat without permission.','The diaphragm starts my chain reaction.','Holding your breath is a common attempted cure.','I am the little “hic” your body makes.']],
['Yawn','involuntary deep breath','Body & Culture','easy',['Reading about me may trigger me.','I spreads socially without being an infection.','My mouth opens wide for a deep breath.','Tired people often do me.','I am a contagious-looking sign of sleepiness.']],
['Goosebumps','raised skin bumps','Body & Culture','easy',['I am more useful on a body with thick fur.','Tiny muscles pull each hair upright.','Cold or strong emotion can cause me.','I make skin look like a plucked bird.','I am the bumps that rise on your skin.']],
['Taste bud','sensory structure','Body & Culture','easy',['I am replaced roughly every couple of weeks.','I do not work alone; smell transforms the experience.','Many of me sit in bumps on the tongue.','I detect qualities such as sweet and bitter.','I am a tiny organ involved in tasting food.']],
['Heartbeat','rhythmic cardiac action','Body & Culture','easy',['My pace changes before a race begins.','Two sounds mark one cycle.','Electrical signals coordinate my rhythm.','A pulse lets you feel me elsewhere.','I am the repeated beating of the heart.']],
['Skeleton','body framework','Body & Culture','easy',['I am lighter and more alive than I look in museums.','Babies begin with more of my pieces than adults.','Joints connect my rigid parts.','I protect organs and support the body.','I am the complete framework of bones.']],
['Tear','drop from the eye','Body & Culture','easy',['I appear for maintenance as well as emotion.','Salt is one of my ingredients.','I wash and protect a delicate surface.','Crying sends me down the cheek.','I am a drop produced by the eye.']],
['Dream','sleep experience','Body & Culture','easy',['I can feel long despite occurring within one night.','Most of me vanish soon after waking.','Rapid eye movement sleep is closely linked with vivid versions of me.','Images and stories unfold in the sleeping mind.','I am an experience you have while asleep.']],
['Laughter','vocal expression of amusement','Body & Culture','easy',['I can spread through a room without explanation.','My rhythm interrupts ordinary breathing.','People do me before they can speak.','Jokes often cause me.','I am the sound of amusement.']],
['Palindrome','reversible word or phrase','Body & Culture','medium',['Direction changes nothing about my sequence.','Spaces and punctuation are often ignored when judging me.','“Level” is one example.','I read the same forward and backward.','I am a symmetrical word or phrase.']],
['Alphabet','ordered letter set','Body & Culture','easy',['My name begins by joining my first two ancestors.','My order is learned even when its logic is not.','I lets spoken language be represented visibly.','English gives me twenty-six members.','I am the ordered set from A to Z.']],
['Exclamation mark','punctuation symbol','Body & Culture','easy',['My lower part stands apart from the rest.','I turn a statement into something louder.','Warnings often place me at the end.','I am a vertical stroke above a dot.','I am the punctuation mark for emphasis or surprise.']],
['Metaphor','figurative comparison','Body & Culture','medium',['I say one thing is another without requiring literal truth.','I can make an abstract idea visible.','Unlike my close cousin, I need no “like” or “as.”','“Time is a thief” uses me.','I am a figure of speech based on comparison.']],
['Sign language','visual language','Body & Culture','easy',['I use space as grammar can use word order.','My many varieties are not mutually identical.','Face and body contribute meaning alongside hands.','Deaf communities develop and use me.','I am language communicated visually through signs.']],
['Handshake','hand-clasp greeting','Body & Culture','easy',['My meaning depends on mutual participation.','I briefly connects two right hands in many cultures.','Business introductions often include me.','A grip and small up-down movement perform me.','I am a greeting made by clasping hands.']],
['Birthday candle','celebration candle','Body & Culture','easy',['More of me can imply less time ahead, though no one says so at the party.','I am extinguished by a wish and one breath.','My count may match someone’s age.','I stand on top of a cake.','I am the small flame blown out at a birthday.']],
['Lullaby','soothing bedtime song','Body & Culture','easy',['My audience may not understand a single word.','Repetition makes me comforting rather than boring.','My tempo is usually gentle.','Adults sing me to babies.','I am a song intended to help someone sleep.']],
['Applause','audience approval sound','Body & Culture','easy',['Many separate impacts become one social signal.','I often begin with one person and spread.','Hands repeatedly meet to create me.','Performers bow when they hear me.','I am an audience clapping.']],
['Bookmark','place-saving marker','Body & Culture','easy',['I remember where you stopped without reading anything.','I should be thin enough not to damage my host.','I wait between pages.','I mark your place in a book.','I am a strip used so you can resume reading.']],
];

const calibratedDifficulty=index=>index%20<8?'easy':index%20<15?'medium':'hard';
export const puzzles=Object.freeze(rows.map(([answer,descriptor,category,_difficulty,hints],index)=>Object.freeze({id:`m-${String(index+1).padStart(3,'0')}`,number:index+1,answer,descriptor,category,difficulty:calibratedDifficulty(index),hints:Object.freeze(hints)})));
export const categories=Object.freeze(['Everything',...[...new Set(puzzles.map(p=>p.category))]]);
export const puzzleById=new Map(puzzles.map(p=>[p.id,p]));
